std::optional<DispatcherNode::ReadyCandidate> DispatcherNode::SelectReadyCandidate() {
  // ---- A6 选车（PeekN 扫描 + 三态处理 + 队首阻塞规避）----
  // 队首任务可能因"暂无合格车辆"而不可派；此时**不能**让整条队列堵死：
