// 死锁快照组包（纯函数）。
//
// 原来这一步内联在 DispatcherNode::BuildDeadlockSnapshot 里，并且**自带副作用**：
// 它一边组包一边就地删掉 pending_wait_ 里的"幽灵等待者"（已不在队列里的任务）。
// 副作用让这块逻辑既不能单测（要造一个 dispatch 节点），也不能被
// DetectTrafficDeadlock 服务安全复用（读操作会改状态）。
//
// 这里拆成"纯组包 + 返回待清扫 id"：调用方拿到 stale_wait_mission_ids 后
// 自己决定何时 erase。语义与原来完全一致（等待者是否有效的判据仍是
// "任务是否还在队列里"），只是把写操作挪到了调用方。
#pragma once

#include <chrono>
#include <string>
#include <unordered_map>
#include <unordered_set>
#include <utility>
#include <vector>

#include "amr_dispatcher_core/dispatcher/deadlock_detector.hpp"
#include "amr_dispatcher_core/dispatcher/mission_state.hpp"

namespace amr_dispatcher_core::dispatcher {

// 组包所需的全部输入（由 ROS 侧从自己的容器里拷出来，core 不持有任何句柄）。
struct DeadlockSnapshotSources {
  // 当前 ACTIVE 的任务（mission_id -> Mission）
  std::unordered_map<std::string, Mission> active_missions;
  // mission_id -> 最近一次进度时刻（缺失视为默认构造值，与原实现一致）
  std::unordered_map<std::string, std::chrono::steady_clock::time_point> last_progress;
  // mission_id -> 路由锁预留成功时刻（长持锁启发式取证）
  std::unordered_map<std::string, std::chrono::steady_clock::time_point> reservation_acquired_at;
  // mission_id -> 该任务此刻在等的资源（Peek 预留失败记下的静态锁）
  std::unordered_map<std::string, std::vector<std::string>> pending_wait;
  // 预约表快照（resource_id -> owner_id）
  std::vector<std::pair<std::string, std::string>> reserved_resources;
  // 当前仍在排队的任务 id 集合：不在其中的等待者视为幽灵，需要清扫。
  // filter_stale_waiters=false 时（队列尚未建立，与原实现 queue_==nullptr 分支一致）
  // 不做幽灵判定，全部等待者原样进图。
  std::unordered_set<std::string> queued_mission_ids;
  bool filter_stale_waiters = true;
};

struct DeadlockSnapshotAssembly {
  DeadlockSnapshot snapshot;
  // 调用方应在组包之后从 pending_wait 里删除这些 key（原实现是就地 erase）
  std::vector<std::string> stale_wait_mission_ids;
};

// 组包。不修改输入，不读时钟，不持有引用。
DeadlockSnapshotAssembly AssembleDeadlockSnapshot(const DeadlockSnapshotSources& sources);

}  // namespace amr_dispatcher_core::dispatcher
=== CPP ===
#include "amr_dispatcher_core/dispatcher/deadlock_snapshot_assembly.hpp"

#include <algorithm>

namespace amr_dispatcher_core::dispatcher {

DeadlockSnapshotAssembly AssembleDeadlockSnapshot(const DeadlockSnapshotSources& sources) {
  DeadlockSnapshotAssembly assembly;
  DeadlockSnapshot& snap = assembly.snapshot;

  // 等待记录只对仍在排队的任务有效：被批量取消/离场的等待者不进 waiting_for
  //（防 WFG 残留幽灵等待者）。原实现是就地 erase，这里改为"记下 id 由调用方删"。
  for (const auto& [mission_id, _] : sources.pending_wait) {
    if (sources.filter_stale_waiters &&
        sources.queued_mission_ids.find(mission_id) == sources.queued_mission_ids.end()) {
      assembly.stale_wait_mission_ids.push_back(mission_id);
    }
  }
  // 稳定的输出顺序：调用方可能按顺序写日志/事件，哈希序会让两次相同输入
  // 产出不同顺序（e2e 断言会因此变成"偶尔不一致"）
  std::sort(assembly.stale_wait_mission_ids.begin(), assembly.stale_wait_mission_ids.end());

  for (const auto& [id, mission] : sources.active_missions) {
    snap.active_missions.push_back(mission);
    const auto progress_it = sources.last_progress.find(id);
    // 缺失 progress 记录时插入默认构造的时间点——与原实现 mission_last_progress_[id]
    // 的隐式插入行为一致（operator[] 语义）
    snap.last_progress[id] = (progress_it == sources.last_progress.end())
                                 ? std::chrono::steady_clock::time_point{}
                                 : progress_it->second;
  }

  // WFG 数据上环：held_by 与预留资源集合来自预约表快照（resource -> owner）
  for (const auto& [resource_id, owner_id] : sources.reserved_resources) {
    snap.allocation_graph.held_by[resource_id] = owner_id;
    snap.reserved_resource_ids.insert(resource_id);
  }

  // waiting_for 只收有效等待者（幽灵等待者已由调用方清扫，这里也不放进去）
  for (const auto& [mission_id, resources] : sources.pending_wait) {
    if (sources.filter_stale_waiters &&
        sources.queued_mission_ids.find(mission_id) == sources.queued_mission_ids.end()) {
      continue;
    }
    snap.allocation_graph.waiting_for[mission_id] = resources;
  }

  snap.reservation_acquired_at = sources.reservation_acquired_at;
  return assembly;
}

}  // namespace amr_dispatcher_core::dispatcher

