struct ReservationAttempt {
  enum class DenialKind {
    kNone,      // 成功（或无需预留）
    kTimeSpace, // 时空窗预约被拒：只告警 + 记账
    kStatic,    // 静态锁被拒：告警 + 记账 + reservation_denied 事件
  };
